# Generate all possible sets of 2k+1 distinct positive integers with sum greater than N
from itertools import combinations
import math

def check_set(nums, N, k):
    # Check if sum of the set is greater than N
    if sum(nums) <= N:
        return False
    # Check if sum of every subset of size k is at most N/2
    for subset in combinations(nums, k):
        if sum(subset) > N/2:
            return False
    return True

def find_set(N, k):
    # Try all possible sets of 2k+1 distinct positive integers
    for i in range(1, 2*k+2):
        for subset in combinations(range(1, i+1), 2*k+1):
            if check_set(list(subset), N, k):
                return subset
    return None

k = 12
N = 3924
set_of_numbers = find_set(N, k)
if set_of_numbers is not None:
    print(set_of_numbers)
else:
    print("No such set found.")
